      }
      {
        float4 vb0 = *reinterpret_cast<const float4*>(&sB(kk, thread_col0));
        b_reg[0] = vb0.x; b_reg[1] = vb0.y; b_reg[2] = vb0.z; b_reg[3] = vb0.w;
      }
