    const bool has_next = (kt + 1) < num_k_tiles;
    float4 regA[LOADS_A];
    int nxt = 1 - buf;
    if (has_next) {
      load_A_tile_to_reg(kt + 1, regA);
      load_B_tile_to_smem_async(kt + 1, nxt);
      cp_async_commit_group();
    }
    compute_tile(buf);
    if (has_next) {
      cp_async_wait_group<0>();
      store_A_reg_to_smem(regA, nxt);
      __syncthreads();
      buf = nxt;
    }
  }
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int gr = block_row + thread_row0 + i;
    if (gr >= M) continue;
    int gc0 = block_col + thread_col0;
    if (gc0 + TN <= N) {
      float4 v0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
      *reinterpret_cast<float4*>(&mC(gr, gc0)) = v0;
    } else {
      #pragma unroll
      for (int j = 0; j < TN; ++j) {
        int gc = gc0 + j;
        if (gc < N) mC(gr, gc) = acc[i][j];
      }
    }
  }
}
torch::Tensor cute_gemm_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions of A and B must match");
  auto Ac = A.contiguous();
  auto Bc = B.contiguous();
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  auto C = torch::empty({M, N}, A.options());
  dim3 block(THREADS_X, THREADS_Y);
  dim3 grid((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_kernel<<<grid, block, 0, stream>>>(
      Ac.data_ptr<float>(),
      Bc.data_ptr<float>(),
      C.data_ptr<float>(),
      M, N, K);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute gemm_kernel launch failed: ", cudaGetErrorString(err));
  return C;
}
