class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A @ B implemented with a custom
    CUDA kernel using CUTE tensors/layouts for tiled shared-memory GEMM.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemm_forward(A.contiguous(), B.contiguous())

